 17	public class Main {
 18	
 19	    public static void main(String[] args) {
 20	        int port = getPort();
 21	
 22	        DataSource dataSource = Database.createDataSource();
 23	
 24	        RoomRepository roomRepository = new RoomRepository(dataSource);
 25	        ReservationRepository reservationRepository = new ReservationRepository(dataSource);
 26	        MessageRepository messageRepository = new MessageRepository(dataSource);
 27	
 28	        NotificationService notificationService = new NotificationService(messageRepository);
 29	
 30	        RoomController roomController = new RoomController(roomRepository);
 31	        ReservationController reservationController = new ReservationController(
 32	            reservationRepository, roomRepository, notificationService
 33	        );
 34	        MessageController messageController = new MessageController(messageRepository);
 35	        ReportController reportController = new ReportController(reservationRepository, roomRepository);
 36	
 37	        ObjectMapper objectMapper = new ObjectMapper();
 38	        objectMapper.registerModule(new JavaTimeModule());
 39	        objectMapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 40	
 41	        Javalin app = Javalin.create(config -> {
 42	            config.jsonMapper(new JavalinJackson(objectMapper, true));
 43	        }).start(port);
 44	
 45	        app.get("/rooms", roomController::getRooms);
 46	        app.post("/reservations", reservationController::createReservation);
 47	        app.get("/reservations/{id}", reservationController::getReservation);
 48	        app.post("/reservations/{id}/confirmation", reservationController::confirmReservation);
 49	        app.post("/reservations/{id}/cancellation", reservationController::cancelReservation);
 50	        app.post("/reservations/{id}/check-in", reservationController::checkInReservation);
 51	        app.post("/reservations/{id}/check-out", reservationController::checkOutReservation);
 52	        app.get("/reservations/{id}/document", reservationController::getDocument);
 53	        app.get("/messages", messageController::getMessages);
 54	        app.get("/reports/occupancy", reportController::getOccupancyReport);
 55	        app.get("/reports/revenue", reportController::getRevenueReport);
 56	
 57	        System.out.println("Pousada Maré Alta - Sistema de Reservas");
 58	        System.out.println("Servidor rodando na porta " + port);
 59	    }
