 61	    private static int getPort() {
 62	        String portEnv = System.getenv("PORT");
 63	        if (portEnv != null && !portEnv.isEmpty()) {
 64	            try {
 65	                return Integer.parseInt(portEnv);
 66	            } catch (NumberFormatException e) {
 67	                System.err.println("Invalid PORT value, using default 7070");
 68	            }
 69	        }
 70	        return 7070;
 71	    }
 72	}
 73	package pousada.api;
 74	
 75	import io.javalin.http.Context;
 76	import pousada.domain.Reservation;
 77	import pousada.domain.Room;
 78	import pousada.repository.ReservationRepository;
 79	import pousada.repository.RoomRepository;
 80	import pousada.service.NotificationService;
 81	
 82	import java.time.LocalDate;
 83	import java.time.format.DateTimeParseException;
 84	import java.util.HashMap;
 85	import java.util.List;
 86	import java.util.Map;
 87	
 88	public class ReservationController {
 89	
 90	    private final ReservationRepository reservationRepository;
 91	    private final RoomRepository roomRepository;
 92	    private final NotificationService notificationService;
 93	
 94	    public ReservationController(ReservationRepository reservationRepository,
 95	                                RoomRepository roomRepository,
 96	                                NotificationService notificationService) {
 97	        this.reservationRepository = reservationRepository;
 98	        this.roomRepository = roomRepository;
 99	        this.notificationService = notificationService;
100	    }
101	
102	    public void createReservation(Context ctx) {
103	        try {
104	            Map<String, Object> body = ctx.bodyAsClass(Map.class);
105	
106	            String roomNumber = getRequiredString(body, "roomNumber");
107	            String guestName = getRequiredString(body, "guestName");
108	            String guestEmail = getRequiredString(body, "guestEmail");
109	            String guestCpf = getRequiredString(body, "guestCpf");
110	            LocalDate checkIn = parseDate(getRequiredString(body, "checkIn"));
111	            LocalDate checkOut = parseDate(getRequiredString(body, "checkOut"));
112	            int guests = getRequiredInt(body, "guests");
113	            String ratePlan = getRequiredString(body, "ratePlan");
114	            String companyCode = (String) body.get("companyCode");
115	
116	            if (!checkOut.isAfter(checkIn)) {
117	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Check-out must be after check-in"));
118	                return;
119	            }
120	
121	            if (guests < 1) {
122	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Number of guests must be at least 1"));
123	                return;
124	            }
125	
126	            Room room = roomRepository.findByNumber(roomNumber)
127	                .orElseThrow(() -> new RoomNotFoundException("Room not found: " + roomNumber));
128	
129	            if (guests > room.capacity()) {
130	                ctx.status(422).json(new ErrorResponse("CAPACITY_EXCEEDED", "Number of guests exceeds room capacity"));
131	                return;
132	            }
133	
134	            List<Reservation> conflicts = reservationRepository.findByRoomAndDateRange(roomNumber, checkIn, checkOut);
135	            if (!conflicts.isEmpty()) {
136	                ctx.status(409).json(new ErrorResponse("ROOM_UNAVAILABLE", "Room is not available for the selected dates"));
137	                return;
138	            }
139	
140	            Reservation reservation = Reservation.create(
141	                roomNumber, room.type(), guestName, guestEmail, guestCpf,
142	                checkIn, checkOut, guests, ratePlan, companyCode
143	            );
144	
145	            reservationRepository.save(reservation);
146	
147	            ctx.status(201).json(toJson(reservation));
148	
149	        } catch (InvalidRequestException | DateTimeParseException e) {
150	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
151	        } catch (RoomNotFoundException e) {
152	            ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", e.getMessage()));
153	        } catch (IllegalArgumentException e) {
154	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
155	        }
156	    }
157	
158	    public void getReservation(Context ctx) {
159	        try {
160	            Long id = Long.parseLong(ctx.pathParam("id"));
161	            Reservation reservation = reservationRepository.findById(id)
162	                .orElseThrow(() -> new ReservationNotFoundException("Reservation not found"));
163	
164	            ctx.json(toJson(reservation));
165	
166	        } catch (NumberFormatException e) {
167	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
168	        } catch (ReservationNotFoundException e) {
169	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
170	        }
171	    }
172	
173	    public void confirmReservation(Context ctx) {
174	        try {
175	            Long id = Long.parseLong(ctx.pathParam("id"));
176	            Reservation reservation = reservationRepository.findById(id)
177	                .orElseThrow(() -> new ReservationNotFoundException("Reservation not found"));
178	
179	            reservation.confirm();
180	            reservationRepository.save(reservation);
181	            notificationService.sendConfirmationEmail(reservation);
182	
183	            ctx.json(toJson(reservation));
184	
185	        } catch (NumberFormatException e) {
186	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
187	        } catch (ReservationNotFoundException e) {
188	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
189	        } catch (IllegalStateException e) {
190	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
191	        }
192	    }
193	
194	    public void cancelReservation(Context ctx) {
195	        try {
196	            Long id = Long.parseLong(ctx.pathParam("id"));
197	            Reservation reservation = reservationRepository.findById(id)
198	                .orElseThrow(() -> new ReservationNotFoundException("Reservation not found"));
199	
200	            reservation.cancel();
201	            reservationRepository.save(reservation);
202	
203	            ctx.json(toJson(reservation));
204	
205	        } catch (NumberFormatException e) {
206	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
207	        } catch (ReservationNotFoundException e) {
208	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
209	        } catch (IllegalStateException e) {
210	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
211	        }
212	    }
213	
214	    public void checkInReservation(Context ctx) {
215	        try {
216	            Long id = Long.parseLong(ctx.pathParam("id"));
217	            Reservation reservation = reservationRepository.findById(id)
218	                .orElseThrow(() -> new ReservationNotFoundException("Reservation not found"));
219	
220	            reservation.doCheckIn();
221	            reservationRepository.save(reservation);
222	
223	            ctx.json(toJson(reservation));
224	
225	        } catch (NumberFormatException e) {
226	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
227	        } catch (ReservationNotFoundException e) {
228	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
229	        } catch (IllegalStateException e) {
230	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
231	        }
232	    }
233	
234	    public void checkOutReservation(Context ctx) {
235	        try {
236	            Long id = Long.parseLong(ctx.pathParam("id"));
237	            Reservation reservation = reservationRepository.findById(id)
238	                .orElseThrow(() -> new ReservationNotFoundException("Reservation not found"));
239	
240	            reservation.doCheckOut();
241	            reservationRepository.save(reservation);
242	
243	            ctx.json(toDocument(reservation));
244	
245	        } catch (NumberFormatException e) {
246	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
247	        } catch (ReservationNotFoundException e) {
248	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
249	        } catch (IllegalStateException e) {
250	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
251	        }
252	    }
253	
254	    public void getDocument(Context ctx) {
255	        try {
256	            Long id = Long.parseLong(ctx.pathParam("id"));
257	            Reservation reservation = reservationRepository.findById(id)
258	                .orElseThrow(() -> new ReservationNotFoundException("Reservation not found"));
259	
260	            if (!reservation.isPaid()) {
261	                ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Document only available for paid reservations"));
262	                return;
263	            }
264	
265	            ctx.json(toDocument(reservation));
266	
267	        } catch (NumberFormatException e) {
268	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
269	        } catch (ReservationNotFoundException e) {
270	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
271	        }
272	    }
273	
274	    private Map<String, Object> toJson(Reservation reservation) {
275	        Map<String, Object> json = new HashMap<>();
276	        json.put("id", reservation.id());
277	        json.put("roomNumber", reservation.roomNumber());
278	        json.put("guestName", reservation.guestName());
279	        json.put("guestEmail", reservation.guestEmail());
280	        json.put("guestCpf", reservation.guestCpf());
281	        json.put("checkIn", reservation.checkIn().toString());
282	        json.put("checkOut", reservation.checkOut().toString());
283	        json.put("guests", reservation.guests());
284	        json.put("ratePlan", reservation.ratePlanName());
285	        json.put("nights", reservation.nights());
286	        json.put("subtotal", reservation.subtotal());
287	        json.put("discount", reservation.discount());
288	        json.put("total", reservation.total());
289	        json.put("status", reservation.status().name());
290	        json.put("amountPaid", reservation.amountPaid());
291	        json.put("refund", reservation.refund());
292	        return json;
293	    }
294	
295	    private Map<String, Object> toDocument(Reservation reservation) {
296	        Map<String, Object> doc = new HashMap<>();
297	        doc.put("title", "Comprovante de reserva");
298	        doc.put("reservationId", reservation.id());
299	        doc.put("guestName", reservation.guestName());
300	        doc.put("guestCpf", reservation.guestCpf());
301	        doc.put("roomNumber", reservation.roomNumber());
302	        doc.put("roomType", reservation.roomType().name());
303	        doc.put("checkIn", reservation.checkIn().toString());
304	        doc.put("checkOut", reservation.checkOut().toString());
305	        doc.put("nights", reservation.nights());
306	        doc.put("subtotal", reservation.subtotal());
307	        doc.put("discount", reservation.discount());
308	        doc.put("total", reservation.total());
309	        return doc;
310	    }
311	
312	    private String getRequiredString(Map<String, Object> body, String key) {
313	        Object value = body.get(key);
314	        if (value == null || !(value instanceof String) || ((String) value).isEmpty()) {
315	            throw new InvalidRequestException("Missing or invalid field: " + key);
316	        }
317	        return (String) value;
318	    }
319	
320	    private int getRequiredInt(Map<String, Object> body, String key) {
321	        Object value = body.get(key);
322	        if (value == null) {
323	            throw new InvalidRequestException("Missing field: " + key);
324	        }
325	        if (value instanceof Number) {
326	            return ((Number) value).intValue();
327	        }
328	        throw new InvalidRequestException("Invalid field type: " + key);
329	    }
330	
331	    private LocalDate parseDate(String dateStr) {
332	        try {
333	            return LocalDate.parse(dateStr);
334	        } catch (DateTimeParseException e) {
335	            throw new InvalidRequestException("Invalid date format: " + dateStr);
336	        }
337	    }
338	
339	    private static class InvalidRequestException extends RuntimeException {
340	        public InvalidRequestException(String message) {
341	            super(message);
342	        }
343	    }
344	
345	    private static class RoomNotFoundException extends RuntimeException {
346	        public RoomNotFoundException(String message) {
347	            super(message);
348	        }
349	    }
350	
351	    private static class ReservationNotFoundException extends RuntimeException {
352	        public ReservationNotFoundException(String message) {
353	            super(message);
354	        }
355	    }
356	}
357	package pousada.config;
358	
359	import com.zaxxer.hikari.HikariConfig;
360	import com.zaxxer.hikari.HikariDataSource;
361	
362	import javax.sql.DataSource;
363	
364	public class Database {
365	
366	    public static DataSource createDataSource() {
367	        String jdbcUrl = System.getenv("DB_URL");
368	        String username = System.getenv("DB_USER");
369	        String password = System.getenv("DB_PASSWORD");
370	
371	        if (jdbcUrl == null || username == null || password == null) {
372	            throw new IllegalStateException("Database configuration not found. Set DB_URL, DB_USER, and DB_PASSWORD environment variables.");
373	        }
374	
375	        HikariConfig config = new HikariConfig();
376	        config.setJdbcUrl(jdbcUrl);
377	        config.setUsername(username);
378	        config.setPassword(password);
379	        config.setMaximumPoolSize(10);
380	
381	        return new HikariDataSource(config);
382	    }
383	}

