225	        } catch (NumberFormatException e) {
226	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
227	        } catch (ReservationNotFoundException e) {
228	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
229	        } catch (IllegalStateException e) {
