314	import java.math.BigDecimal;
315	import java.math.RoundingMode;
316	import java.time.DayOfWeek;
317	import java.time.LocalDate;
318	import java.time.Month;
319	
320	public abstract class AbstractRatePlan implements RatePlan {
321	
322	    protected static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
323	
324	    protected BigDecimal round(BigDecimal value) {
325	        return value.setScale(2, RoundingMode.HALF_EVEN);
326	    }
327	
328	    protected boolean isHighSeason(LocalDate date) {
329	        Month month = date.getMonth();
330	        int day = date.getDayOfMonth();
331	
332	        if (month == Month.JULY) {
333	            return true;
334	        }
335	
336	        if (month == Month.DECEMBER && day >= 15) {
337	            return true;
338	        }
339	
340	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
341	            return true;
342	        }
343	
344	        return false;
345	    }
346	
347	    protected BigDecimal calculateNightPrice(LocalDate night, RoomType roomType) {
348	        BigDecimal baseRate = roomType.nightlyRate();
349	        if (isHighSeason(night)) {
350	            return round(baseRate.multiply(HIGH_SEASON_MULTIPLIER));
351	        }
352	        return baseRate;
353	    }
354	
355	    protected BigDecimal calculateSubtotalForNights(LocalDate checkIn, LocalDate checkOut, RoomType roomType) {
356	        BigDecimal subtotal = BigDecimal.ZERO;
357	        LocalDate current = checkIn;
358	
359	        while (current.isBefore(checkOut)) {
360	            subtotal = subtotal.add(calculateNightPrice(current, roomType));
361	            current = current.plusDays(1);
362	        }
363	
364	        return round(subtotal);
365	    }
366	
367	    protected long countNights(LocalDate checkIn, LocalDate checkOut) {
368	        return checkOut.toEpochDay() - checkIn.toEpochDay();
369	    }
370	
371	    protected boolean isWeekendPackagePeriod(LocalDate checkIn, LocalDate checkOut) {
372	        return checkIn.getDayOfWeek() == DayOfWeek.FRIDAY &&
373	               checkOut.getDayOfWeek() == DayOfWeek.SUNDAY &&
374	               countNights(checkIn, checkOut) == 2;
375	    }
376	}
