    10	public class MessageRepository {
    11	
    12	    private final DataSource dataSource;
    13	
    14	    public MessageRepository(DataSource dataSource) {
    15	        this.dataSource = dataSource;
    16	        createTable();
    17	    }
    18	
    19	    private void createTable() {
    20	        String sql = """
    21	            CREATE TABLE IF NOT EXISTS messages (
    22	                id BIGSERIAL PRIMARY KEY,
    23	                channel VARCHAR(20) NOT NULL,
    24	                recipient VARCHAR(255) NOT NULL,
    25	                subject VARCHAR(500) NOT NULL,
    26	                body TEXT NOT NULL
    27	            )
    28	            """;
    29	
    30	        try (Connection conn = dataSource.getConnection();
    31	             Statement stmt = conn.createStatement()) {
    32	            stmt.execute(sql);
    33	        } catch (SQLException e) {
    34	            throw new RuntimeException("Failed to create messages table", e);
    35	        }
    36	    }
    37	
    38	    public Message save(Message message) {
    39	        String sql = "INSERT INTO messages (channel, recipient, subject, body) VALUES (?, ?, ?, ?)";
    40	
    41	        try (Connection conn = dataSource.getConnection();
    42	             PreparedStatement pstmt = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
    43	
    44	            pstmt.setString(1, message.channel());
    45	            pstmt.setString(2, message.to());
    46	            pstmt.setString(3, message.subject());
    47	            pstmt.setString(4, message.body());
    48	            pstmt.executeUpdate();
    49	
    50	            try (ResultSet rs = pstmt.getGeneratedKeys()) {
    51	                if (rs.next()) {
    52	                    message.setId(rs.getLong(1));
    53	                }
    54	            }
    55	
    56	            return message;
    57	        } catch (SQLException e) {
    58	            throw new RuntimeException("Failed to save message", e);
    59	        }
    60	    }
    61	
    62	    public List<Message> findAll() {
    63	        List<Message> messages = new ArrayList<>();
    64	        String sql = "SELECT * FROM messages ORDER BY id";
