   381	    private void initializeRooms() {
   382	        try (Connection conn = dataSource.getConnection()) {
   383	            String checkSql = "SELECT COUNT(*) FROM rooms";
   384	            try (Statement stmt = conn.createStatement();
   385	                 ResultSet rs = stmt.executeQuery(checkSql)) {
   386	                if (rs.next() && rs.getInt(1) > 0) {
   387	                    return;
   388	                }
   389	            }
   390	
   391	            String insertSql = "INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (?, ?, ?, ?)";
   392	            try (PreparedStatement pstmt = conn.prepareStatement(insertSql)) {
