   462	public class NotificationService {
   463	
   464	    private final MessageRepository messageRepository;
   465	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("dd/MM/yyyy");
   466	    private static final NumberFormat CURRENCY_FORMAT = NumberFormat.getCurrencyInstance(new Locale("pt", "BR"));
   467	
   468	    public NotificationService(MessageRepository messageRepository) {
   469	        this.messageRepository = messageRepository;
   470	    }
   471	
   472	    public void sendConfirmationEmail(Reservation reservation) {
   473	        String receipt = generateReceipt(reservation);
   474	        String emailBody = String.format("""
   475	            Olá, %s!
   476	
   477	            Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:
   478	
   479	            %s
   480	
   481	            A entrada é a partir das 14h, e a saída, até as 12h.
   482	            Até breve!""", reservation.guestName(), receipt);
   483	
   484	        Message message = new Message(
   485	            null,
   486	            "EMAIL",
   487	            reservation.guestEmail(),
   488	            "Reserva confirmada - Pousada Maré Alta",
   489	            emailBody
   490	        );
   491	
   492	        messageRepository.save(message);
   493	    }
   494	
   495	    public String generateReceipt(Reservation reservation) {
   496	        StringBuilder sb = new StringBuilder();
   497	        sb.append(String.format("Comprovante de reserva nº %d%n", reservation.id()));
   498	        sb.append(String.format("Hóspede: %s (CPF %s)%n", reservation.guestName(), formatCpf(reservation.guestCpf())));
   499	        sb.append(String.format("Quarto: %s (%s)%n", reservation.roomNumber(), reservation.roomType()));
   500	        sb.append(String.format("Entrada: %s | Saída: %s | %s%n",
   501	            reservation.checkIn().format(DATE_FORMATTER),
   502	            reservation.checkOut().format(DATE_FORMATTER),
   503	            formatNights(reservation.nights())));
   504	        sb.append(String.format("Diárias: %s%n", formatCurrency(reservation.subtotal())));
   505	
   506	        if (reservation.discount().compareTo(java.math.BigDecimal.ZERO) > 0) {
   507	            sb.append(String.format("Desconto: %s%n", formatCurrency(reservation.discount())));
   508	        }
   509	
   510	        sb.append(String.format("Total: %s", formatCurrency(reservation.total())));
   511	
   512	        return sb.toString();
   513	    }
   514	
   515	    private String formatCpf(String cpf) {
   516	        if (cpf.length() == 11) {
   517	            return String.format("%s.%s.%s-%s",
   518	                cpf.substring(0, 3),
   519	                cpf.substring(3, 6),
   520	                cpf.substring(6, 9),
   521	                cpf.substring(9, 11));
   522	        }
   523	        return cpf;
   524	    }
   525	
   526	    private String formatCurrency(java.math.BigDecimal value) {
   527	        return CURRENCY_FORMAT.format(value);
   528	    }
   529	
   530	    private String formatNights(long nights) {
   531	        return nights == 1 ? "1 diária" : nights + " diárias";
   532	    }
   533	}
