   557	    public void getOccupancyReport(Context ctx) {
   558	        try {
   559	            String dateStr = ctx.queryParam("date");
   560	            if (dateStr == null || dateStr.isEmpty()) {
   561	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing date parameter"));
   562	                return;
   563	            }
   564	
   565	            LocalDate date = LocalDate.parse(dateStr);
   566	            List<Reservation> reservations = reservationRepository.findByDate(date);
   567	            List<Room> allRooms = roomRepository.findAll();
   568	
   569	            StringBuilder csv = new StringBuilder();
   570	            csv.append("room,type,reservation,check_in,check_out\n");
   571	
   572	            for (Reservation reservation : reservations) {
   573	                csv.append(String.format("%s,%s,%d,%s,%s\n",
   574	                    reservation.roomNumber(),
   575	                    reservation.roomType().name(),
   576	                    reservation.id(),
   577	                    reservation.checkIn(),
   578	                    reservation.checkOut()
   579	                ));
   580	            }
   581	
   582	            csv.append(String.format("total,%d/%d\n", reservations.size(), allRooms.size()));
   583	
