   592	    public void getRevenueReport(Context ctx) {
   593	        try {
   594	            String monthStr = ctx.queryParam("month");
   595	            if (monthStr == null || monthStr.isEmpty()) {
   596	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing month parameter"));
   597	                return;
   598	            }
   599	
   600	            String[] parts = monthStr.split("-");
   601	            if (parts.length != 2) {
   602	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid month format"));
   603	                return;
   604	            }
   605	
   606	            int year = Integer.parseInt(parts[0]);
   607	            int month = Integer.parseInt(parts[1]);
   608	
   609	            List<Reservation> reservations = reservationRepository.findByMonth(year, month);
   610	
   611	            StringBuilder csv = new StringBuilder();
   612	            csv.append("reservation,room,check_in,check_out,status,amount\n");
   613	
   614	            BigDecimal total = BigDecimal.ZERO;
   615	
   616	            for (Reservation reservation : reservations) {
   617	                BigDecimal revenue = reservation.amountPaid().subtract(
   618	                    reservation.refund() != null ? reservation.refund() : BigDecimal.ZERO
   619	                );
   620	
   621	                if (revenue.compareTo(BigDecimal.ZERO) > 0) {
   622	                    csv.append(String.format("%d,%s,%s,%s,%s,%s\n",
   623	                        reservation.id(),
   624	                        reservation.roomNumber(),
   625	                        reservation.checkIn(),
   626	                        reservation.checkOut(),
   627	                        reservation.status().name(),
   628	                        formatCsvDecimal(revenue)
   629	                    ));
   630	
   631	                    total = total.add(revenue);
   632	                }
   633	            }
   634	
   635	            csv.append(String.format("total,%s\n", formatCsvDecimal(total)));
   636	
   637	            ctx.contentType("text/csv; charset=utf-8");
   638	            ctx.result(csv.toString());
   639	
   640	        } catch (NumberFormatException | DateTimeParseException e) {
   641	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid month format"));
   642	        }
   643	    }
   644	
   645	    private String formatCsvDecimal(BigDecimal value) {
   646	        return value.toString();
   647	    }
   648	}
