268	public class RoomRepository {
269	
270	    private final DataSource dataSource;
271	
272	    public RoomRepository(DataSource dataSource) {
273	        this.dataSource = dataSource;
274	        createTable();
275	        initializeRooms();
276	    }
277	
278	    private void createTable() {
279	        String sql = """
280	            CREATE TABLE IF NOT EXISTS rooms (
281	                number VARCHAR(10) PRIMARY KEY,
282	                type VARCHAR(20) NOT NULL,
283	                capacity INTEGER NOT NULL,
284	                nightly_rate DECIMAL(10,2) NOT NULL
285	            )
286	            """;
287	
288	        try (Connection conn = dataSource.getConnection();
289	             Statement stmt = conn.createStatement()) {
290	            stmt.execute(sql);
291	        } catch (SQLException e) {
292	            throw new RuntimeException("Failed to create rooms table", e);
293	        }
294	    }
295	
296	    private void initializeRooms() {
297	        try (Connection conn = dataSource.getConnection()) {
298	            String checkSql = "SELECT COUNT(*) FROM rooms";
299	            try (Statement stmt = conn.createStatement();
300	                 ResultSet rs = stmt.executeQuery(checkSql)) {
301	                if (rs.next() && rs.getInt(1) > 0) {
302	                    return;
303	                }
304	            }
305	
306	            String insertSql = "INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (?, ?, ?, ?)";
307	            try (PreparedStatement pstmt = conn.prepareStatement(insertSql)) {
308	                insertRoom(pstmt, "101", RoomType.STANDARD);
309	                insertRoom(pstmt, "102", RoomType.STANDARD);
310	                insertRoom(pstmt, "201", RoomType.DELUXE);
311	                insertRoom(pstmt, "202", RoomType.DELUXE);
312	                insertRoom(pstmt, "301", RoomType.SUITE);
313	            }
314	        } catch (SQLException e) {
315	            throw new RuntimeException("Failed to initialize rooms", e);
316	        }
317	    }
318	
319	    private void insertRoom(PreparedStatement pstmt, String number, RoomType type) throws SQLException {
320	        pstmt.setString(1, number);
321	        pstmt.setString(2, type.name());
322	        pstmt.setInt(3, type.capacity());
323	        pstmt.setBigDecimal(4, type.nightlyRate());
324	        pstmt.executeUpdate();
325	    }
326	
327	    public List<Room> findAll() {
328	        List<Room> rooms = new ArrayList<>();
329	        String sql = "SELECT number, type FROM rooms ORDER BY number";
330	
331	        try (Connection conn = dataSource.getConnection();
332	             Statement stmt = conn.createStatement();
333	             ResultSet rs = stmt.executeQuery(sql)) {
334	
335	            while (rs.next()) {
336	                String number = rs.getString("number");
337	                RoomType type = RoomType.valueOf(rs.getString("type"));
338	                rooms.add(new Room(number, type));
339	            }
340	        } catch (SQLException e) {
341	            throw new RuntimeException("Failed to fetch rooms", e);
342	        }
343	
344	        return rooms;
345	    }
346	
347	    public Optional<Room> findByNumber(String number) {
348	        String sql = "SELECT number, type FROM rooms WHERE number = ?";
349	
350	        try (Connection conn = dataSource.getConnection();
351	             PreparedStatement pstmt = conn.prepareStatement(sql)) {
352	
353	            pstmt.setString(1, number);
354	            try (ResultSet rs = pstmt.executeQuery()) {
355	                if (rs.next()) {
356	                    RoomType type = RoomType.valueOf(rs.getString("type"));
357	                    return Optional.of(new Room(number, type));
358	                }
359	            }
360	        } catch (SQLException e) {
361	            throw new RuntimeException("Failed to fetch room", e);
362	        }
363	
364	        return Optional.empty();
365	    }
366	}

