 10	
 11	public class NotificationService {
 12	
 13	    private final MessageRepository messageRepository;
 14	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("dd/MM/yyyy");
 15	    private static final NumberFormat CURRENCY_FORMAT = NumberFormat.getCurrencyInstance(new Locale("pt", "BR"));
 16	
 17	    public NotificationService(MessageRepository messageRepository) {
 18	        this.messageRepository = messageRepository;
 19	    }
 20	
 21	    public void sendConfirmationEmail(Reservation reservation) {
 22	        String receipt = generateReceipt(reservation);
 23	        String emailBody = String.format("""
 24	            Olá, %s!
 25	
 26	            Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:
 27	
 28	            %s
 29	
 30	            A entrada é a partir das 14h, e a saída, até as 12h.
 31	            Até breve!""", reservation.guestName(), receipt);
 32	
 33	        Message message = new Message(
 34	            null,
 35	            "EMAIL",
 36	            reservation.guestEmail(),
 37	            "Reserva confirmada - Pousada Maré Alta",
 38	            emailBody
 39	        );
 40	
 41	        messageRepository.save(message);
 42	    }
 43	
 44	    public String generateReceipt(Reservation reservation) {
 45	        StringBuilder sb = new StringBuilder();
 46	        sb.append(String.format("Comprovante de reserva nº %d%n", reservation.id()));
 47	        sb.append(String.format("Hóspede: %s (CPF %s)%n", reservation.guestName(), formatCpf(reservation.guestCpf())));
 48	        sb.append(String.format("Quarto: %s (%s)%n", reservation.roomNumber(), reservation.roomType()));
 49	        sb.append(String.format("Entrada: %s | Saída: %s | %s%n",
 50	            reservation.checkIn().format(DATE_FORMATTER),
 51	            reservation.checkOut().format(DATE_FORMATTER),
 52	            formatNights(reservation.nights())));
 53	        sb.append(String.format("Diárias: %s%n", formatCurrency(reservation.subtotal())));
 54	
 55	        if (reservation.discount().compareTo(java.math.BigDecimal.ZERO) > 0) {
 56	            sb.append(String.format("Desconto: %s%n", formatCurrency(reservation.discount())));
 57	        }
 58	
 59	        sb.append(String.format("Total: %s", formatCurrency(reservation.total())));
 60	
 61	        return sb.toString();
 62	    }
 63	
 64	    private String formatCpf(String cpf) {
 65	        if (cpf.length() == 11) {
 66	            return String.format("%s.%s.%s-%s",
 67	                cpf.substring(0, 3),
 68	                cpf.substring(3, 6),
 69	                cpf.substring(6, 9),
 70	                cpf.substring(9, 11));
 71	        }
 72	        return cpf;
 73	    }
 74	
 75	    private String formatCurrency(java.math.BigDecimal value) {
 76	        return CURRENCY_FORMAT.format(value);
 77	    }
 78	
 79	    private String formatNights(long nights) {
 80	        return nights == 1 ? "1 diária" : nights + " diárias";
 81	    }
 82	}
