162	
163	            BigDecimal total = BigDecimal.ZERO;
164	
165	            for (Reservation reservation : reservations) {
166	                BigDecimal revenue = reservation.amountPaid().subtract(
167	                    reservation.refund() != null ? reservation.refund() : BigDecimal.ZERO
168	                );
169	
170	                if (revenue.compareTo(BigDecimal.ZERO) > 0) {
171	                    csv.append(String.format("%d,%s,%s,%s,%s,%s\n",
172	                        reservation.id(),
173	                        reservation.roomNumber(),
174	                        reservation.checkIn(),
175	                        reservation.checkOut(),
176	                        reservation.status().name(),
177	                        formatCsvDecimal(revenue)
178	                    ));
179	
180	                    total = total.add(revenue);
181	                }
182	            }
183	
184	            csv.append(String.format("total,%s\n", formatCsvDecimal(total)));
185	
186	            ctx.contentType("text/csv; charset=utf-8");
187	            ctx.result(csv.toString());
188	
189	        } catch (NumberFormatException | DateTimeParseException e) {
190	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid month format"));
191	        }
